import {readFile, writeFile} from 'node:fs/promises';

const [inputPath, outputPath] = process.argv.slice(2);
if (!inputPath || !outputPath) {
  throw new Error('Usage: node embed-manifest.mjs <manifest.json> <generatedManifest.js>');
}

const manifest = JSON.parse(await readFile(inputPath, 'utf8'));
if (
  manifest?.schemaVersion !== 1 ||
  !manifest?.manifestId ||
  !Array.isArray(manifest?.operations)
) {
  throw new Error('The supplied file is not a valid InkBridge schema-1 manifest.');
}
const javascript =
  '// Generated by supernote-poc/embed-manifest.mjs. Do not edit.\\n' +
  `export const EMBEDDED_MANIFEST = ${JSON.stringify(manifest)};\\n`;
await writeFile(outputPath, javascript, 'utf8');
